func resolveStatusRepairComponent(ctx, params, specIDStr, slotName, workItemIDStr string, logger) (pcID uuid.UUID, resolvedBy, reason string, ok bool) {
    // stable key: page_id lives on the work item ROW, not in the dispatch payload
    rows, qErr := params.DB.QueryContext(ctx, `
        SELECT pc.id FROM page_components pc
        JOIN site_work_items wi ON wi.page_id = pc.page_id
        WHERE wi.id = $1 AND pc.slot_name = $2 ORDER BY pc.id`, workItemID, slotName)
    // qErr -> fall through to the stored id (fail open)
    switch {
    case len(matches) == 1:  return matches[0], "page_id+slot_name", "", true
    case len(matches) > 1:   // 17 such pairs exist fleet-wide, worst case 4
        for _, m := range matches { if specIDValid && m == specID { return m, "page_id+slot_name+stored_id_tiebreak", "", true } }
        return uuid.Nil, "", "slot %q resolves to %d components on this page and the stored page_component_id is not one of them — refusing to guess which", false
    }
    if specIDValid { return specID, "spec.page_component_id", "", true }
    return uuid.Nil, "", "no usable subject: …", false
}
